function parseCandidateBlocks(text) {
    const blocks = [
        ...text.matchAll(/(?:【\s*候选开始\s*】|<\s*(?:候选|技艺|功法)\s*>)([\s\S]*?)(?:【\s*候选结束\s*】|<\s*\/\s*(?:候选|技艺|功法)\s*>)/g),
    ];
    const candidates = [];
    const allowedFields = new Set(['名称', '类型', '效果', '属性加成', '描述']);
    for (const match of blocks) {
        const candidate = {};
        let currentField = '';
        for (const rawLine of match[1].split(/\r?\n/)) {
            const line = rawLine.trim();
            if (!line)
                continue;
            const fieldMatch = line.match(/^(?:[-*]\s*)?(?:\*{1,2})?(名称|类型|效果|属性加成|描述)(?:\*{1,2})?\s*[：:]\s*(.*)$/);
            if (fieldMatch) {
                currentField = fieldMatch[1];
                candidate[currentField] = fieldMatch[2].trim();
            }
            else if (currentField && allowedFields.has(currentField)) {
                candidate[currentField] = `${candidate[currentField]}\n${line}`.trim();
            }
        }
        if (candidate.名称 && candidate.效果)
            candidates.push(candidate);
    }
    return candidates;
}
function parseTechniquesResult(result) {
    const text = typeof result === 'string' ? result : result.content || JSON.stringify(result);
    console.info('[功法分支] AI 返回原始文本（前300字）:', text.slice(0, 300));
    const blockCandidates = parseCandidateBlocks(text);
    if (blockCandidates.length > 0) {
        console.info(`[功法分支] 从候选字段块解析出 ${blockCandidates.length} 个条目`);
        return blockCandidates;
    }
    console.info('[功法分支] 未找到候选字段块，尝试兼容旧 JSON 输出');
    const parsed = extractJSON(text);
    const obj = parsed;
    let techniques;
    if (Array.isArray(obj)) {
        techniques = obj;
    }
    else if (obj && typeof obj === 'object') {
        techniques = obj.techniques ?? obj.功法 ?? obj.data ?? obj;
        if (!Array.isArray(techniques)) {
            techniques = Object.values(obj).find(Array.isArray) ?? techniques;
        }
    }
    else {
        techniques = obj;
    }
    if (!Array.isArray(techniques)) {
        throw new Error('AI 返回的分支数据不是数组');
    }
    return techniques;
}
// ── 校验 ──────────────────────────────────────────────
function validateBranch(techniques, triggerName, targetLevel, existingNames) {
    const 合法 = [];
    for (const raw of techniques) {
        const t = 映射字段名(raw);
        if (!t.名称 || typeof t.名称 !== 'string' || !t.名称.trim())
            continue;
        t.名称 = t.名称.trim();
        if (existingNames.has(t.名称)) {
            console.info(`[功法分支] 跳过重复名称: ${t.名称}`);
            continue;
        }
        const parsed = AI功法条目Schema.safeParse(t);
        if (!parsed.success) {
            console.warn(`[功法分支] 跳过无法修正的条目: ${JSON.stringify(t)}`, parsed.error.issues);
            continue;
        }
        const 功 = parsed.data;
        existingNames.add(功.名称);
        // 树结构字段由程序确定，不接受模型自行指定。
        if (功.层级 !== targetLevel) {
            console.info(`[功法分支] 调整层级: ${功.名称} 从 ${功.层级} 调整为 ${targetLevel}`);
            功.层级 = targetLevel;
        }
        功.前置功法 = triggerName;
        功.已学习 = false;
        合法.push(功);
    }
    return 合法;
}
